$ aws s3api get-bucket-versioning --bucket data-bucket
{ "Status": "Enabled" }

$ aws s3api list-object-versions --bucket data-bucket --prefix report/
{ "Versions": [ {"VersionId":"v2","IsLatest":true}, {"VersionId":"v1","IsLatest":false} ] }

$ aws s3api get-object --bucket data-bucket --key report/secret.pdf --version-id v1 out.pdf
# содержимое v1: nto{s3_v3rs10n_r3c0v3r}
